function createMockPlatformAdapter(
  opts: {
    joinDelay?: number;
    joinError?: string;
    audioChunks?: AudioChunk[];
    leaveError?: string;
  } = {},
): MockPlatformAdapter {
  const participantJoinCbs: ((p: Participant) => void)[] = [];
  const participantLeaveCbs: ((id: string) => void | Promise<void>)[] = [];
  const participants: Participant[] = [];
  const audioChunks =
    opts.audioChunks ??
    [
      {
        data: new Uint8Array(96000),
        encoding: 'pcm_s16le',
        timestamp: 1000,
        sampleRate: 48000,
        channels: 1,
      },
      {
        data: new Uint8Array(96000),
        encoding: 'pcm_s16le',
        timestamp: 2000,
        sampleRate: 48000,
        channels: 1,
      },
    ];

  return {
    platform: 'zoom',
    async join(_url, _config) {
      if (opts.joinDelay) {
        await new Promise((r) => setTimeout(r, opts.joinDelay));
      }
      if (opts.joinError) {
        throw new Error(opts.joinError);
      }
    },
    async leave() {
      if (opts.leaveError) {
        throw new Error(opts.leaveError);
      }
    },
    getAudioStream() {
      return new ReadableStream<AudioChunk>({
        start(controller) {
          for (const chunk of audioChunks) {
            controller.enqueue(chunk);
          }
          controller.close();
        },
      });
    },
    getVideoStream() {
      return new ReadableStream({ start(c) {
        for (let i = 0; i < 20; i++) c.enqueue({ data: new Uint8Array(16 * 16 * 3), encoding: 'rgb24', frameRate: 10, timestamp: 1000 + i * 100, width: 16, height: 16 });
        c.close();
      } });
    },
    async getParticipants() {
      return participants;
    },
    onParticipantJoin(cb) {
      participantJoinCbs.push(cb);
    },
    onParticipantLeave(cb) {
      participantLeaveCbs.push(cb);
    },
    async emitParticipantLeave(participantId = 'participant_1') {
      await Promise.all(participantLeaveCbs.map((cb) => cb(participantId)));
    },
    async getChatMessages() {
      return [];
